add_action( 'woocommerce_after_shop_loop_item', 'perfectpixel_text_under_products', 9 );

function perfectpixel_text_under_products() {
	$categories = wp_parse_id_list( '{{loop_extra_text_category_ids}}' );
	if ( $categories && ! has_term( $categories, 'product_cat', get_the_ID() ) ) {
		return;
	}
	echo '<div class="perfectpixel-loop-text" style="font-size:.85em;margin:.5em 0">' . wp_kses_post( '{{loop_extra_text}}' ) . '</div>';
}
